import json
import os
from web3 import Web3

class BlockchainClient:
    def __init__(self, rpc_url="http://127.0.0.1:7545"):
        self.w3 = Web3(Web3.HTTPProvider(rpc_url))
        
        # Load contract data generated by deploy.py
        current_dir = os.path.dirname(os.path.abspath(__file__))
        data_path = os.path.join(current_dir, "contract_data.json")
        
        try:
            with open(data_path, "r") as f:
                data = json.load(f)
                self.contract_address = data["address"]
                self.abi = data["abi"]
        except FileNotFoundError:
            print("Warning: contract_data.json not found. You must deploy the contract first.")
            self.contract_address = None
            self.abi = None
            
        if self.contract_address and self.abi and self.w3.is_connected():
            self.contract = self.w3.eth.contract(address=self.contract_address, abi=self.abi)
            # We assume node accounts[0] is the deployer/gateway
            self.gateway_account = self.w3.eth.accounts[0] 
        else:
            self.contract = None
            
    def is_authorized(self, device_address: str) -> bool:
        """
        Calls the Zero Trust `verifyAccess` functionality in the blockchain.
        Does not cost gas since it's a read-only View.
        """
        if not self.contract:
            print("ERROR: Not connected to blockchain contract.")
            return False
            
        try:
            is_valid = self.contract.functions.verifyAccess(device_address).call()
            return is_valid
        except Exception as e:
            print(f"Blockchain Verification Error: {e}")
            return False
            
    def log_event(self, device_address: str, action: str, status: str, metadata: str) -> bool:
        """
        Logs a transaction into the block event logs. Mutates state and costs gas.
        This provides an immutable audit trail.
        """
        if not self.contract:
            return False
            
        try:
            tx_hash = self.contract.functions.logEvent(
                device_address, action, status, metadata
            ).transact({"from": self.gateway_account})
            
            # Wait for block confirmation (fast in local chains)
            self.w3.eth.wait_for_transaction_receipt(tx_hash)
            return True
        except Exception as e:
            print(f"Blockchain Logging Error: {e}")
            return False
